<?php require __DIR__.'/includes/bootstrap.php';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf()){http_response_code(403);$cart_error='Your session expired. Please try again.';}else{$action=(string)($_POST['action']??'');if($action==='add'){cart_add((string)($_POST['id']??''),(int)($_POST['quantity']??1));}elseif($action==='set'){cart_set((string)($_POST['id']??''),(int)($_POST['quantity']??0));}elseif($action==='remove'){unset($_SESSION['cart'][$_POST['id']]);}}}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Shopping Cart | TraveL Den Shop</title><meta name="description" content="Review your physical artefacts and trinkets shopping cart."><link rel="stylesheet" href="/shop/assets/css/shop.css"></head><body><?php require __DIR__.'/includes/header.php'; ?>
<h1>Shopping cart</h1><?php if(!empty($cart_error)):?><p class="notice"><?= shop_e($cart_error) ?></p><?php endif;?><?php $items=cart_items();if(!$items):?><p>Your cart is empty.</p><a class="shop-button" href="/shop/products.php">Continue shopping</a><?php else:?><table class="cart-table"><thead><tr><th>Product</th><th>Quantity</th><th>Unit price</th><th>Line total</th><th>Action</th></tr></thead><tbody><?php foreach($items as $item):$p=$item['product'];?><tr><td><img src="<?= shop_e($p['main_image']) ?>" alt="<?= shop_e($p['name']) ?>"><strong><?= shop_e($p['name']) ?></strong></td><td><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="set"><input type="hidden" name="id" value="<?= shop_e($p['id']) ?>"><label class="field-label"><span class="sr-only">Quantity for <?= shop_e($p['name']) ?></span><input type="number" name="quantity" min="0" max="<?= (int)$p['stock'] ?>" value="<?= (int)$item['quantity'] ?>"></label><button class="shop-button secondary" type="submit">Update</button></form></td><td><?= shop_money($p['price']) ?></td><td><?= shop_money($item['line_total']) ?></td><td><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="remove"><input type="hidden" name="id" value="<?= shop_e($p['id']) ?>"><button class="shop-button danger" type="submit">Remove</button></form></td></tr><?php endforeach;?></tbody></table><aside class="cart-summary"><div class="summary-row"><strong>Subtotal</strong><strong><?= shop_money(cart_subtotal()) ?> KES</strong></div><div class="summary-row"><span>Delivery cost</span><span>Calculated at checkout</span></div><p><a class="shop-button secondary" href="/shop/products.php">Continue shopping</a></p><p><a class="shop-button" href="/shop/checkout.php">Proceed to checkout</a></p></aside><?php endif;?><?php require __DIR__.'/includes/footer.php'; ?></body></html>
